(* [comment removed for export] *)
Definition sr_i_exit (p : srp) (ra sp gp tp s0 s1 s2 s3 s5 s7 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' s4' s6' s8' s9' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 0) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4' s5 s6' s7 s8' s9' (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x9e48c) fc None m' (seg_rom asegs)
    /\ munch [(sr_DD p, sr_DD p + sr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma sr_i_loop : forall (n : nat) (p : srp) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a5 a6 a7 s2 s3 s5 s7 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = sr_h p - i -> 0 <= i -> (1 <= n)%nat -> sr_ok p ->
  (forall m', munch [(sr_DD p, sr_DD p + sr_ND p)] m m' -> wmono asegs m m' -> sr_ro p m') ->
  wr_at asegs m (sr_DD p) (sr_ND p) -> acc asegs m (sr_DD p) (sr_ND p) -> mem_inv asegs m ->
  evt asegs (sr_i_exit p ra sp gp tp s0 s1 s2 s3 s5 s7 s11 t3 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 i) (Z_to_bv 64 (sr_DD p + 4 * sr_w p * i + sr_c p)) (Z_to_bv 64 (sr_w p)) (Z_to_bv 64 (4 * sr_w p)) a5 a6 a7
             s2 s3 (Z_to_bv 64 (4 * sr_wpls p)) s5 (Z_to_bv 64 (sr_DS p + 4 * sr_wpls p * i)) s7 (Z_to_bv 64 (sr_w p)) (Z_to_bv 64 (sr_h p))
             (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x9e31c) fc None m (seg_rom asegs)).
