    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1 (Z_to_bv 64 (gr_w p)) a3 a4 (Z_to_bv 64 (gr_w p)) (Z_to_bv 64 (LS + 4 * gr_w p)) (Z_to_bv 64 (LD + gr_w p))
