    /\ munch [(gr_DD p, gr_DD p + gr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.
Lemma gr_j_loop : forall (n : nat) (p : grp) (j LS LD : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 s2 s3 s4 s7 s8 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gr_w p - j -> 0 <= j -> (1 <= n)%nat -> gr_ok p ->
  gr_DS p <= LS -> LS + 4 * gr_w p < gr_DS p + gr_NS p + 4 -> gr_DD p <= LD -> LD + gr_w p <= gr_DD p + gr_ND p ->
  (forall m', munch [(gr_DD p, gr_DD p + gr_ND p)] m m' -> wmono asegs m m' -> gr_ro p m') ->
  wr_at asegs m (gr_DD p) (gr_ND p) -> acc asegs m (gr_DD p) (gr_ND p) -> mem_inv asegs m ->
  evt asegs (gr_j_exit p LS LD ra sp gp tp s0 s1 a0 a1 a3 a4 s2 s3 s4 s7 s8 s9 s10 t3 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 (Z_to_bv 64 j) (Z_to_bv 64 (LS + 4 * j)) (Z_to_bv 64 (LD + j))
             s2 s3 s4 (Z_to_bv 64 (gr_FW p)) (Z_to_bv 64 (gr_FH p)) s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 t4 t5 t6)
        F (Z_to_bv 64 0x9de68) fc None m (seg_rom asegs)).
