(* [comment removed for export] *)
Definition gr_i_exit (p : grp) (ra sp gp tp s0 s1 a0 s2 s3 s7 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' s4' s5' s6' s8' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0 a1' a2' a3' a4' a5' a6' a7' s2 s3 s4' s5' s6' s7 s8' s9 s10 (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 0x9df80) fc None m' (seg_rom asegs)
    /\ munch [(gr_DD p, gr_DD p + gr_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma gr_i_loop : forall (n : nat) (p : grp) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a5 a6 a7 s2 s3 s7 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gr_h p - i -> 0 <= i -> (1 <= n)%nat -> gr_ok p ->
  (forall m', munch [(gr_DD p, gr_DD p + gr_ND p)] m m' -> wmono asegs m m' -> gr_ro p m') ->
  wr_at asegs m (gr_DD p) (gr_ND p) -> acc asegs m (gr_DD p) (gr_ND p) -> mem_inv asegs m ->
  evt asegs (gr_i_exit p ra sp gp tp s0 s1 a0 s2 s3 s7 s9 s10 t3 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (gr_DD p + 4 * gr_wpld p * i)) a2 (Z_to_bv 64 i) (Z_to_bv 64 (4 * gr_w p)) a5 a6 a7
             s2 s3 (Z_to_bv 64 (gr_DS p + gr_c p + 4 * gr_w p * i)) (Z_to_bv 64 (gr_FW p)) (Z_to_bv 64 (gr_FH p)) s7 (Z_to_bv 64 (4 * gr_wpld p)) s9 s10
             (Z_to_bv 64 2147450880) t3 t4 t5 t6)
